class GridPos(NamedTuple):
    """"""

    y: int
    x: int


class ChainData(TypedDict):
    """"""

    qcmzcjocmj: Dict[int, GridPos]
    oxbwsencfv: int


def parse_chain_maps(
    wcbywgdovp: Dict[str, Dict[str, List[List[int]]]],
) -> Dict[str, Dict[str, ChainData]]:
    """"""
    zzdjlqxdnf: Dict[str, Dict[str, ChainData]] = {}
    for uwtopyjnbz, vpuoorisew in wcbywgdovp.items():
        ccqkbwunoh: Dict[str, ChainData] = {}
        for ihcexiqgys, axevtouupo in vpuoorisew.items():
            qcmzcjocmj: Dict[int, GridPos] = {}
            oxbwsencfv = 0
            for y, pxycedmqtn in enumerate(axevtouupo):
                for x, rchyrnavey in enumerate(pxycedmqtn):
                    if rchyrnavey != -1:
                        if rchyrnavey in qcmzcjocmj:
                            raise ValueError(f"Duplicate number {rchyrnavey} in map '{ihcexiqgys}' of level '{uwtopyjnbz}'")
                        qcmzcjocmj[rchyrnavey] = GridPos(y, x)
                        if rchyrnavey > oxbwsencfv:
                            oxbwsencfv = rchyrnavey
            ccqkbwunoh[ihcexiqgys] = {"qcmzcjocmj": qcmzcjocmj, "oxbwsencfv": oxbwsencfv}
        zzdjlqxdnf[uwtopyjnbz] = ccqkbwunoh
    return zzdjlqxdnf


def get_move_pairs(
    uwtopyjnbz: str,
    ihcexiqgys: str,
    kiofvrbmju: bool,
    uopmnplcnv: Dict[str, Dict[str, ChainData]],
) -> List[Tuple[GridPos, GridPos]]:
    """"""
    gdmraryfrp: ChainData = uopmnplcnv[uwtopyjnbz][ihcexiqgys]
    qcmzcjocmj: Dict[int, GridPos] = gdmraryfrp["qcmzcjocmj"]
    oxbwsencfv: int = gdmraryfrp["oxbwsencfv"]
    if oxbwsencfv <= 1:
        return []
    nvjnzzyham: List[Tuple[GridPos, GridPos]] = []
    for acnxhwymfw, pmpudfwvhx in qcmzcjocmj.items():
        ibwabdeure: int
        if kiofvrbmju:
            ibwabdeure = 1 if acnxhwymfw == oxbwsencfv else acnxhwymfw + 1
        else:
            ibwabdeure = oxbwsencfv if acnxhwymfw == 1 else acnxhwymfw - 1
        kvtywzwzuc: GridPos = qcmzcjocmj[ibwabdeure]
        nvjnzzyham.append((pmpudfwvhx, kvtywzwzuc))
    return nvjnzzyham


class StepProgressBar(RenderableUserDisplay):
    """"""

    rrhqvpezjr: List[Tuple[int, int]]

    def __init__(self, bnlfrvxkob: int, zigwldrikf: int = 1, level_index: int = 0):
        self.bnlfrvxkob = bnlfrvxkob
        self.current_steps = bnlfrvxkob
        self.zigwldrikf = max(1, zigwldrikf)
        self.level_index = level_index
        self.rrhqvpezjr = self._build_pixel_positions()

    def set_steps(self, tozynaoupn: int) -> None:
        self.current_steps = max(0, min(tozynaoupn, self.bnlfrvxkob))

    def decrement_and_check(self) -> bool:
        if self.current_steps > 0:
            self.current_steps -= 1
        return self.current_steps > 0

    def reset_steps(self) -> None:
        self.current_steps = self.bnlfrvxkob

    def update_level_info(self, zigwldrikf: int, level_index: int) -> None:
        self.zigwldrikf = max(1, zigwldrikf)
        self.level_index = min(level_index - 1, zigwldrikf - 1)

    @staticmethod
    def _build_pixel_positions() -> List[Tuple[int, int]]:
        """"""
        cbymhlqajy: List[Tuple[int, int]] = []
        for y in range(0, 64):
            cbymhlqajy.append((0, y))
        return cbymhlqajy

    def render_interface(self, frame: np.ndarray) -> np.ndarray:
        if self.bnlfrvxkob == 0:
            return frame
        vhemackyeq = (self.bnlfrvxkob - self.current_steps) / self.bnlfrvxkob
        mvinexidwb = round(len(self.rrhqvpezjr) * vhemackyeq)
        for bgneslizza, (x, y) in enumerate(self.rrhqvpezjr):
            frame[y, x] = BLACK if bgneslizza < mvinexidwb else GREEN
        for i in range(self.zigwldrikf):
            start_x = 10 + i * 5
            start_y = 1
            for sbgijpvxnc in range(4):
                frame[start_y, start_x + sbgijpvxnc] = GREEN if i <= self.level_index else BLACK
        return frame


class Lp85(ARCBaseGame):
    def __init__(self) -> None:
        kccdfjnrxn = levels[0].get_data("StepCounter") if levels else 0
        bnlfrvxkob = kccdfjnrxn if kccdfjnrxn else 0
        self.toxpunyqe = StepProgressBar(bnlfrvxkob, zigwldrikf=len(levels), level_index=0)
        self.uopmnplcnv = parse_chain_maps(chain_maps)
        qroguobpp = Camera(
            width=16,
            height=16,
            background=BACKGROUND_COLOR,
            letter_box=PADDING_COLOR,
            interfaces=[self.toxpunyqe],
        )



        self._log_state = ActionLogState(aggregator=default_aggregator, post_process=compose_default_summary)




        self._last_reported_progress: int = -1









        self._last_logged_level_index: int = 0


        self._frame_sprite_log:       list[list[dict]] = []
        self._frame_nonsprite_log:    list[list[dict]] = []

        super().__init__(game_id="lp85", levels=levels, camera=qroguobpp, available_actions=[6])
        self._init_step_counter()

    def _init_step_counter(self) -> None:
        """"""
        nolvdnrgxa = self.current_level.get_data("StepCounter")
        if nolvdnrgxa:
            self.toxpunyqe.bnlfrvxkob = nolvdnrgxa
            self.toxpunyqe.reset_steps()

    def on_set_level(self, level: Level) -> None:
        """"""
        self._init_step_counter()

        self._last_reported_progress = -1
        isjnflak = self.current_level.grid_size
        if isjnflak is not None:
            self.kshrbnrfkopq = isjnflak[0]
            self.papamfmeoa = isjnflak[1]
        self.toxpunyqe.update_level_info(zigwldrikf=len(levels), level_index=self.level_index)
        self.ucybisahh = self.current_level.get_data("level_name")
        self.afhycvvjg = self.current_level.get_sprites_by_tag("sys_click")
        qsdpkqvbun: set[tuple[int, int]] = set()
        for s in self.afhycvvjg:
            if (s.x, s.y) in qsdpkqvbun:
                s.tags.remove("sys_click")
            else:
                qsdpkqvbun.add((s.x, s.y))






        _name_counts: dict[str, int] = {}
        for spr in self.current_level.get_sprites():
            _name_counts[spr.name] = _name_counts.get(spr.name, 0) + 1
        _to_rename = {name for name, count in _name_counts.items() if count >= 2}
        if _to_rename:
            _idx_per_name: dict[str, int] = {name: 0 for name in _to_rename}
            for spr in self.current_level.get_sprites():
                if spr.name in _to_rename:
                    _idx_per_name[spr.name] += 1
                    spr.set_name(f"{spr.name}_{_idx_per_name[spr.name]}")







        _LAYOUT_TAGS: dict[str, tuple[str, str]] = {
            "tile":        ("tile",                ""),
            "goal":        ("goal_tile_yellow",    "()"),
            "goal-o":      ("goal_tile_orange",    "()"),
            "goal_yellow": ("goal_marker_yellow",  "()"),
            "goal_orange": ("goal_marker_orange",  "()"),
            "sys_click":   ("clickable_button",    ""),
        }
        _layout_rows: list[dict] = []
        for _spr in self.current_level.get_sprites():
            if not _spr.is_visible:
                continue



            _tag_set = set(_spr.tags or [])
            _matched = None
            for _candidate in ("tile", "goal", "goal-o", "goal_yellow", "goal_orange", "sys_click"):
                if _candidate in _tag_set:
                    _matched = _LAYOUT_TAGS[_candidate]
                    break
            if _matched is None:
                continue
            _role, _role_l2 = _matched
            _dx, _dy, _dw, _dh = self._to_display_bbox(_spr)
            _layout_rows.append({
                "role":    _role,
                "role_l2": _role_l2,
                "sname":   _spr.name,
                "dx": _dx, "dy": _dy, "dw": _dw, "dh": _dh,
            })


        try:
            _ns_status = self.get_nonsprite_status() or []
        except Exception:
            _ns_status = []
        for _ns in _ns_status:
            _ns_name = _ns.get("name", "")
            if _ns_name == "step_bar":
                _role, _role_l2 = "remaining_step", ""
            elif _ns_name == "level_progress":
                _role, _role_l2 = "level_progress", ""
            else:
                continue
            _layout_rows.append({
                "role":    _role,
                "role_l2": _role_l2,
                "sname":   _ns_name,
                "dx": int(_ns.get("x", 0)),
                "dy": int(_ns.get("y", 0)),
                "dw": int(_ns.get("width", 0)),
                "dh": int(_ns.get("height", 0)),
            })

        if _layout_rows:
            self._set_event("initial_layout", _layout_rows)










        if self.level_index > self._last_logged_level_index:
            _new_done = self.level_index
            _max_lv   = len(levels)
            _dot_x    = 10 + _new_done * 5
            if _new_done < _max_lv:
                en = (
                    f"[change]:[level_progress]:[sname(level_progress);color(black)_(green);"
                    f"position({_dot_x}_1);bbox(4_1)]:"
                    f"The level progress gauge dot at ({_dot_x},1) turns green — Lv{_new_done} cleared "
                    f"({_new_done} of {_max_lv} levels done)."
                    f"|The Object at ({_dot_x},1) turns green ({_new_done} of {_max_lv})."
                )
                l2 = (
                    f"[change]:[level_progress]:[sname(level_progress);color(black)_(green);"
                    f"position({_dot_x}_1);bbox(4_1)]:"
                    f"({_dot_x},1)—"
                    f"Lv{_new_done} {_new_done}/{_max_lv}"
                    f"|({_dot_x},1)Object{_new_done}/{_max_lv}"
                )
                self._frame_action_logs.append([en])
                if hasattr(self, "_frame_action_logs_l2"):
                    self._frame_action_logs_l2.append([l2])

                if hasattr(self, "_frame_sprite_log"):
                    self._frame_sprite_log.append(self.get_sprite_status())
                if hasattr(self, "_frame_nonsprite_log"):
                    self._frame_nonsprite_log.append(self.get_nonsprite_status())
            self._last_logged_level_index = self.level_index

    def _display_for(self, name: str) -> tuple[str, str, str]:
        """









        """
        result = SPRITE_DISPLAY.get(name)
        if result is not None:
            return result
        import re as _re
        _base = _re.sub(r"_\d+$", "", name)
        if _base != name and _base in SPRITE_DISPLAY:
            return SPRITE_DISPLAY[_base]
        return (name, name, name)

    def _to_display_xy(self, x: int, y: int) -> tuple[int, int]:
        """



        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        return (x - cam.x) * arc_scale + x_off, (y - cam.y) * arc_scale + y_off


    def _to_display_bbox(self, spr) -> tuple[int, int, int, int]:
        """

        """
        cam = self.camera
        arc_scale = min(64 // cam.width, 64 // cam.height)
        x_off = (64 - cam.width  * arc_scale) // 2
        y_off = (64 - cam.height * arc_scale) // 2
        dx = (spr.x - cam.x) * arc_scale + x_off
        dy = (spr.y - cam.y) * arc_scale + y_off
        dw = spr.width  * arc_scale
        dh = spr.height * arc_scale
        return dx, dy, dw, dh

    def _bar_pixel_len(self, current_steps: int) -> int:
        """


        """
        bar = self.toxpunyqe
        total = bar.bnlfrvxkob
        if total == 0:
            return 0
        used = total - current_steps
        if used < 0:
            used = 0
        if used > total:
            used = total
        return round(len(bar.rrhqvpezjr) * used / total)

    def _get_sprite_at_exact(self, x: int, y: int) -> Sprite | None:
        for sprite in self.current_level._sprites:
            if sprite.x == x and sprite.y == y:
                return sprite
        return None

    def _get_sprites_at(self, x: int, y: int) -> List[Sprite] | None:
        sprites = []
        for sprite in self.current_level._sprites:
            if x >= sprite.x and y >= sprite.y and (x < sprite.x + sprite.width) and (y < sprite.y + sprite.height):
                sprites.append(sprite)
        if len(sprites) > 0:
            return sprites
        return None

    def step(self) -> None:
        """













        """

        self.action_log    = []
        self.action_log_l2 = []




        _before_sprites = {
            id(spr): {
                "name": spr.name,
                "x": spr.x, "y": spr.y,
                "width": spr.width, "height": spr.height,
                "rotation": spr.rotation,
                "visible": spr.is_visible,
            }
            for spr in self.current_level.get_sprites()
        }
        _before_steps = self.toxpunyqe.current_steps




        button_clicked = False
        if self.action.id == GameAction.ACTION6:
            x = self.action.data.get("x", 0)
            y = self.action.data.get("y", 0)
            vshsqyfvro = self.camera.display_to_grid(x, y)
            if vshsqyfvro:
                yrtwgqlvm, ejftlnclv = vshsqyfvro
                cwpawmamb = self._get_sprites_at(yrtwgqlvm, ejftlnclv)
                if cwpawmamb is not None:
                    for pnrmgmcmh in cwpawmamb:
                        if pnrmgmcmh is not None and pnrmgmcmh.tags is not None and ("button" in pnrmgmcmh.tags[0]):
                            button_clicked = True
                            qrjqfnfrjr = pnrmgmcmh.tags[0].split("_")
                            if len(qrjqfnfrjr) == 3:
                                chain_id  = qrjqfnfrjr[1]
                                direction = qrjqfnfrjr[2]
                                is_forward = (direction == "R")
                                dshozwexhv = get_move_pairs(
                                    self.ucybisahh,
                                    chain_id,
                                    is_forward,
                                    self.uopmnplcnv,
                                )
                                cywbpycapt = []
                                for pmpudfwvhx, kvtywzwzuc in dshozwexhv:
                                    dbonbayerv = self._get_sprite_at_exact(
                                        pmpudfwvhx.x * TILE_SIZE,
                                        pmpudfwvhx.y * TILE_SIZE,
                                    )
                                    if dbonbayerv:
                                        cywbpycapt.append((dbonbayerv, kvtywzwzuc))
                                for rpuvbbtfbq, ckyxhqnvtd in cywbpycapt:
                                    rpuvbbtfbq.set_position(
                                        ckyxhqnvtd.x * TILE_SIZE,
                                        ckyxhqnvtd.y * TILE_SIZE,
                                    )

        if not button_clicked:
            self.complete_action()
            return


        if self._check_win():
            self._set_event("win", {
                "en": "[win]:[game]:[]:All goal tiles are placed on their goal markers — the level is cleared.|The level is cleared.",
                "l2": "[win]:[game]:[]:|",
            })




            if hasattr(self, "_frame_sprite_log"):
                self._frame_sprite_log.append(self.get_sprite_status())
            if hasattr(self, "_frame_nonsprite_log"):
                self._frame_nonsprite_log.append(self.get_nonsprite_status())
            self._log_state.snapshot_step()
            self.next_level()
            self.complete_action()
            return


        still_alive = self.toxpunyqe.decrement_and_check()
        remaining = self.toxpunyqe.current_steps
        total     = self.toxpunyqe.bnlfrvxkob
        if self._bar_pixel_len(_before_steps) != self._bar_pixel_len(remaining):
            self.action_log.append(
                f"[change]:[steps]:[sname(step_bar);count({_before_steps})_({remaining})]:The green step bar on the left edge shrinks from the top ({_before_steps}→{remaining} steps remain, max {total}).|The green Object on the left edge shrinks from the top ({_before_steps}→{remaining}, max {total})."
            )
            self.action_log_l2.append(
                f"[change]:[steps]:[sname(step_bar);count({_before_steps})_({remaining})]:{_before_steps}→{remaining}{total}|Object{_before_steps}→{remaining}{total}"
            )




        after_sprites_list = self.current_level.get_sprites()
        after_sprites = {id(spr): spr for spr in after_sprites_list}


        for spr_id, spr in after_sprites.items():
            b = _before_sprites.get(spr_id)
            appeared = (b is None) or (not b["visible"] and spr.is_visible)
            if appeared:
                dx, dy, dw, dh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr.name)
                self.action_log.append(f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_le} appears at ({dx},{dy}).|Object appears at ({dx},{dy}).")
                self.action_log_l2.append(f"[appear]:[{_t}]:[sname({spr.name});position({dx}_{dy});bbox({dw}_{dh})]:{_l2}({dx},{dy})|Object({dx},{dy})")



        _arc_scale_d = min(64 // self.camera.width, 64 // self.camera.height)
        for spr_id, b in _before_sprites.items():
            spr = after_sprites.get(spr_id)
            disappeared = (spr is None and b["visible"]) or (spr is not None and b["visible"] and not spr.is_visible)
            if disappeared:
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                bdw = int(b.get("width", 0))  * _arc_scale_d
                bdh = int(b.get("height", 0)) * _arc_scale_d
                _t, _le, _l2 = self._display_for(b['name'])
                self.action_log.append(f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_le} disappears from ({bdx},{bdy}).|Object disappears from ({bdx},{bdy}).")
                self.action_log_l2.append(f"[disappear]:[{_t}]:[sname({b['name']});position({bdx}_{bdy});bbox({bdw}_{bdh})]:{_l2}({bdx},{bdy})|Object({bdx},{bdy})")


        for spr_id, spr in after_sprites.items():
            if not spr.is_visible:
                continue
            b = _before_sprites.get(spr_id)
            if b is None or not b["visible"]:
                continue
            if (spr.x, spr.y) != (b["x"], b["y"]):
                bdx, bdy = self._to_display_xy(b["x"], b["y"])
                adx, ady, adw, adh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr.name)
                self.action_log.append(
                    f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{_le} moves from ({bdx},{bdy}) to ({adx},{ady}).|Object moves from ({bdx},{bdy}) to ({adx},{ady})."
                )
                self.action_log_l2.append(
                    f"[move]:[{_t}]:[sname({spr.name});position({bdx}_{bdy})_({adx}_{ady});bbox({adw}_{adh})]:{_l2}({bdx},{bdy})({adx},{ady})|Object({bdx},{bdy})({adx},{ady})"
                )
            if spr.rotation != b["rotation"]:
                _rdx, _rdy, _rdw, _rdh = self._to_display_bbox(spr)
                _t, _le, _l2 = self._display_for(spr.name)
                self.action_log.append(
                    f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:{_le} at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°.|Object at ({_rdx},{_rdy}) rotates from {b['rotation']}° to {spr.rotation}°."
                )
                self.action_log_l2.append(
                    f"[rotate]:[{_t}]:[sname({spr.name});position({_rdx}_{_rdy});bbox({_rdw}_{_rdh});angle({b['rotation']})_({spr.rotation})]:({_rdx},{_rdy}){_l2}{b['rotation']}°{spr.rotation}°|({_rdx},{_rdy})Object{b['rotation']}°{spr.rotation}°"
                )


        if hasattr(self, "_frame_sprite_log"):
            self._frame_sprite_log.append(self.get_sprite_status())
        if hasattr(self, "_frame_nonsprite_log"):
            self._frame_nonsprite_log.append(self.get_nonsprite_status())
        self._log_state.snapshot_step()


        if not still_alive:
            self._set_event("gameover", {
                "en": "[gameover]:[game]:[]:Step counter reached zero, game over.|Game over.",
                "l2": "[gameover]:[game]:[]:0|",
            })
            self.lose()

        self.complete_action()

    def _check_win(self) -> bool:
        """





        """
        ngnionqsbv = self.current_level.get_sprites_by_tag("goal_yellow")
        for praflotbfn in ngnionqsbv:
            if self.current_level.get_sprite_at(praflotbfn.x + 1, praflotbfn.y + 1, "goal") is None:
                return False
        ngnionqsbv = self.current_level.get_sprites_by_tag("goal_orange")
        for praflotbfn in ngnionqsbv:
            if self.current_level.get_sprite_at(praflotbfn.x + 1, praflotbfn.y + 1, "goal-o") is None:
                return False
        return True

    def _count_goal_progress(self) -> tuple[int, int]:
        """



        """
        m = 0
        n = 0
        for marker in self.current_level.get_sprites_by_tag("goal_yellow"):
            n += 1
            if self.current_level.get_sprite_at(marker.x + 1, marker.y + 1, "goal") is not None:
                m += 1
        for marker in self.current_level.get_sprites_by_tag("goal_orange"):
            n += 1
            if self.current_level.get_sprite_at(marker.x + 1, marker.y + 1, "goal-o") is not None:
                m += 1
        return m, n

    def _set_event(self, key: str, value) -> None:
        """
        """
        self._log_state.set_event(key, value)


    @property
    def action_log(self) -> list[str]:
        return self._log_state._step_log
    @action_log.setter
    def action_log(self, value: list[str]) -> None:
        self._log_state._step_log = value

    @property
    def action_log_l2(self) -> list[str]:
        return self._log_state._step_log_l2
    @action_log_l2.setter
    def action_log_l2(self, value: list[str]) -> None:
        self._log_state._step_log_l2 = value

    @property
    def _frame_action_logs(self) -> list[list[str]]:
        return self._log_state._frames
    @_frame_action_logs.setter
    def _frame_action_logs(self, value: list[list[str]]) -> None:
        self._log_state._frames = value

    @property
    def _frame_action_logs_l2(self) -> list[list[str]]:
        return self._log_state._frames_l2
    @_frame_action_logs_l2.setter
    def _frame_action_logs_l2(self, value: list[list[str]]) -> None:
        self._log_state._frames_l2 = value

    def reset_logs(self) -> None:
        self._log_state.reset()



    def get_action_log_frame(self) -> tuple[list[list[str]], list[list[str]]]:
        return self._log_state.get_frame_logs()

    def get_action_log(self) -> tuple[list[str], list[str]]:
        return self._log_state.get_action_log()

    def get_sprite_status(self) -> list[dict]:
        """




        """
        result = []
        for spr in self.current_level.get_sprites():
            if not spr.is_visible:
                continue
            tags     = list(spr._tags) if spr._tags else []
            label    = next(
                (TAG_DISPLAY_NAMES[t] for t in tags if t in TAG_DISPLAY_NAMES),
                spr.name,
            )
            label_l2 = next(
                (TAG_DISPLAY_NAMES_L2[t] for t in tags if t in TAG_DISPLAY_NAMES_L2),
                spr.name,
            )
            result.append({
                "spr_id":   id(spr),
                "name":     spr.name,
                "label":    label,
                "label_l2": label_l2,
                "tags":     tags,
                "x":        spr.x,
                "y":        spr.y,
                "width":    spr.width,
                "height":   spr.height,
                "rotation": spr.rotation,
            })
        return result

    def get_nonsprite_status(self) -> list[dict]:
        """





        """
        result = []


        result.append({
            "name":     "step_bar",
            "label":    "Steps Remaining",
            "label_l2": ''                     ,
            "value":    self.toxpunyqe.current_steps,
            "max":      self.toxpunyqe.bnlfrvxkob,
            "x":        0, "y":      0,
            "width":    1, "height": 64,
        })




        _zigwldrikf = self.toxpunyqe.zigwldrikf
        result.append({
            "name":     "level_progress",
            "label":    "Level Progress",
            "label_l2": ''               ,
            "value":    self.level_index + 1,
            "max":      _zigwldrikf,
            "x":        10, "y":      1,
            "width":    max(0, 5 * _zigwldrikf - 1), "height": 1,
        })

        return result

    def get_game_knowledge(self) -> dict:
        """

        """
        return GAME_KNOWLEDGE
